	private static CanonicalStagedInput stage(LmdbBulkLoader loader, BulkLoadWorkspace workspace,
			BulkTaskScheduler scheduler, InputStream input, String baseUri, RDFFormat format) throws IOException {
		if (ParallelStager.applicable(loader, List.of(format))) {
			// The caller owns the stream: parallel staging must not close it.
			InputStream callerOwned = new FilterInputStream(input) {
				@Override
				public void close() {
				}
			};
			return ParallelStager.stage(loader, workspace, scheduler,
					List.of(new ParallelStager.Input(() -> callerOwned, format, baseUri, null)));
		}
		try (CanonicalStatementStager stager = new CanonicalStatementStager(workspace.directory(), loader.format(),
				loader.partitionCount(), loader.maxOpenFiles(), loader.memoryBudgetBytes(),
				workspace.compression())) {
			parse(loader, workspace, stager, input, baseUri, format, null);
			return stager.stagedInput();
		}
	}

	private static CanonicalStagedInput stage(LmdbBulkLoader loader, BulkLoadWorkspace workspace,
			BulkTaskScheduler scheduler, List<LmdbBulkLoader.PathInput> inputs) throws IOException {
		if (ParallelStager.applicable(loader, inputs.stream().map(LmdbBulkLoader.PathInput::format).toList())) {
			List<ParallelStager.Input> parallelInputs = new ArrayList<>(inputs.size());
			for (int index = 0; index < inputs.size(); index++) {
				LmdbBulkLoader.PathInput input = inputs.get(index);
				Path path = input.path();
				parallelInputs.add(new ParallelStager.Input(() -> Files.newInputStream(path), input.format(),
						path.toString(), inputs.size() > 1 ? FastNTriplesParser.blankNodeScope(index) : null));
			}
			return ParallelStager.stage(loader, workspace, scheduler, parallelInputs);
		}
		try (CanonicalStatementStager stager = new CanonicalStatementStager(workspace.directory(), loader.format(),
				loader.partitionCount(), loader.maxOpenFiles(), loader.memoryBudgetBytes(),
				workspace.compression())) {
			for (int index = 0; index < inputs.size(); index++) {
				LmdbBulkLoader.PathInput input = inputs.get(index);
				checkCancelled(loader);
				try (InputStream stream = Files.newInputStream(input.path())) {
					parse(loader, workspace, stager, stream, input.baseUri(), input.format(),
							inputs.size() > 1 ? FastNTriplesParser.blankNodeScope(index) : null);
				}
			}
			return stager.stagedInput();
		}
	}

	private static void parse(LmdbBulkLoader loader, BulkLoadWorkspace workspace, CanonicalStatementStager stager,
			InputStream input, String baseUri, RDFFormat format, byte[] blankNodeScope) throws IOException {
		if (useFastParser(loader, format)) {
			FastNTriplesParser fastParser = new FastNTriplesParser(format, loader.cancellationSignal());
			fastParser.blankNodeScope(blankNodeScope);
			fastParser.parse(input, (subject, predicate, object, context) -> {
				stager.writeCanonicalStatement(subject, predicate, object, context);
				workspace.progress(1L, statementBytes(subject, predicate, object, context));
			});
			checkCancelled(loader);
			return;
		}
		RDFParser parser = parser(loader, format);
		parser.setRDFHandler(new AbstractRDFHandler() {
			@Override
			public void handleNamespace(String prefix, String uri) throws RDFHandlerException {
				checkCancelled(loader);
				try {
					stager.writeNamespace(prefix, uri);
				} catch (IOException e) {
					throw new RDFHandlerException(e);
				}
			}

			@Override
			public void handleStatement(Statement statement) throws RDFHandlerException {
				checkCancelled(loader);
				try {
					stager.writeStatement(statement);
					workspace.progress(1L, 0L);
				} catch (IOException e) {
					throw new RDFHandlerException(e);
				}
			}
		});
		parser.parse(decompressIfRequired(input), baseUri);
		checkCancelled(loader);
	}

	private static long statementBytes(byte[] subject, byte[] predicate, byte[] object, byte[] context) {
		long bytes = Math.addExact(Math.addExact(subject.length, predicate.length), object.length);
		return Math.addExact(bytes, context == null ? 0L : context.length);
	}

	private static long nativeRecordCount(ValueStoreBulkRecords.Output records) {
		long count = Math.addExact(records.mainRecords().records(), records.referenceCounts().records());
		count = Math.addExact(count, records.tripleTerms().rows());
		return Math.addExact(count, records.valueHashes().rows());
	}

	private static InputStream decompressIfRequired(InputStream input) throws IOException {
		BufferedInputStream buffered = input instanceof BufferedInputStream existing
				? existing
				: new BufferedInputStream(input, 64 * 1024);
		buffered.mark(2);
		int first = buffered.read();
		int second = buffered.read();
		buffered.reset();
		return first == 0x1f && second == 0x8b ? new GZIPInputStream(buffered, 64 * 1024) : buffered;
	}

	private static RDFParser parser(LmdbBulkLoader loader, RDFFormat format) throws IOException {
		return Rio.createParser(format);
	}

	private static boolean useFastParser(LmdbBulkLoader loader, RDFFormat format) throws IOException {
		if (loader.parserMode() == LmdbBulkLoader.ParserMode.RIO) {
			return false;
		}
		if (FastNTriplesParser.supports(format)) {
			return true;
		}
		if (loader.parserMode() == LmdbBulkLoader.ParserMode.FAST) {
			throw new IOException("Fast parser only supports N-Triples and N-Quads");
		}
		return false;
	}

	private static void checkCancelled(LmdbBulkLoader loader) {
		if (Thread.currentThread().isInterrupted() || loader.cancellationSignal().getAsBoolean()) {
			throw new CancellationException("LMDB bulk load was cancelled");
		}
	}

	@FunctionalInterface
	private interface StagingAction {

		CanonicalStagedInput stage(BulkLoadWorkspace workspace, BulkTaskScheduler scheduler) throws IOException;
	}
